import os
import json

class CustomSST2(ClassificationDatasetAccess):
    name = "custom_sst2"
    map_labels = False
    x_column = 'text'
    y_label = 'label'
    x_prefix = 'Review: '
    y_prefix = 'Sentiment: '

    def __init__(self):
        data_dir = '/workspace/custom_dataset_extracted/sst2_jsonl'
        train_path = os.path.join(data_dir, 'train.jsonl')
        test_path = os.path.join(data_dir, 'test.jsonl')
        self.train_df = self._load_jsonl(train_path)
        self.test_df = self._load_jsonl(test_path)
        self.label_mapping = {0: 'negative', 1: 'positive'}

    def _load_jsonl(self, path):
        with open(path, 'r') as f:
            rows = [json.loads(line) for line in f if line.strip()]
        for row in rows:
            row['text'] = row.pop('sentence')
            # Remap -1 to 0 (negative), 1 to 1 (positive)
            if row['label'] == -1:
                row['label'] = 0
            elif row['label'] == 1:
                row['label'] = 1
            else:
                raise ValueError('Unexpected label value in custom_sst2 data')
        import pandas as pd
        return pd.DataFrame(rows)

